INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1033792-math333', 'stk-user5643', 'MATH 333', 'info', '{"desc": "اول شي في هالكورس بتدرس تشابتر 9\n\nوهو مراجعه و توسع للماتيريال الاخير من ماث 201 ( double & triple integrals)\n\nهالجزء هذا سهل و انصح الجميع انه يحرص عليه و لا يفوته في ميجر ون\n\nميججر توو\n\nch 4 & ch 12\n\nتشابتر فور : لابلاس ترانسفورمز … و هذا اهم شي بهالكورس و راح تحتاج له كثيييييير ب me 413\n\nسهل ممتنع … يبيله براكتس … تحتاج فيه\n\npartial fraction & integration & factorization\n\nch 12 شوي غريب هالتشابتر … راح تقدر تحل اسالته مو صعبه بس تحس انه مو مفيد او ممتع زي ch4\n\nهذا ماتيريال ميجر توو … برضو سهل ممتنع و لاتفوته\n\nنجي الحين لماتيريال الفاينال\n\nشي غريب … غير عن كل كورسات الماث الي اخذناها … حتى الدكاتره تحس انهم مو فاهمينه مره … لو تحفظ طريقة الاقزامبلز خلاص ارتاح لان نفسها راح تتجي مع تغير كم رقم\nHeat equation & laplace equation & fourior transforms & partial differential eq\n\nهذا الي اذكره\n\nماتيريال الفاينال هو المشكله الوحيده بهالكورس عشان كذا استغل ميجر ون و تو", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-333-methods-of-applied-mathematics/120619/5", "user": "user5643", "ts": 1336382874000, "tid": 120619, "pn": 5}}', 1336382874000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1077453-math333', 'stk-user5216', 'MATH 333', 'info', '{"desc": "الكورس سهل , عدا اخر جزء منه ( بعد ميجر 2 ) يعتمد ع الحفظ اكثر من الفهم\nواذا انت مزبط ميجر ون وتو … فماراح ياثر عليك الفاينال لانك مو بس انت لحالك الي منت حال كويس كل الشعب مثلك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-333-methods-of-applied-mathematics/120619/7", "user": "user5216", "ts": 1344371874000, "tid": 120619, "pn": 7}}', 1344371874000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1162049-math333', 'stk-metallic', 'MATH 333', 'info', '{"desc": "ميجر ون وميجر تو سهلة جداً جداً جداً …\n\nمتيريل الفاينل هذا شيء صراحة أعتبره أعلى من قدراتي العقلية 😆\n\nدرجاتي بميجر ون وتو أعلى من 80 ، والأفرج أقل من 70 في الاثنين وفي الفاينل مستحيل آخذ أكثر من 60 من 140 !!!\n\nفاينل يجيب الهم صراحة والحمدلله خلصنا من هالكورس !", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-333-methods-of-applied-mathematics/120619/8", "user": "METALLIC", "ts": 1357885319000, "tid": 120619, "pn": 8}}', 1357885319000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1370486-math333', 'stk-zee-mmm', 'MATH 333', 'info', '{"desc": "الماده سهله\nاللي بياخذها بعد الماث 202 راح يرتاح\nالميجر الاول والثاني تافهات\nالفاينل الشعب متعقد منه انا أشوف سهل لو تتابع مع دكتورك\nالصيف راح يكون ضغط لكن سهلات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-333-methods-of-applied-mathematics/120619/19", "user": "ZEE-MMM", "ts": 1400938990000, "tid": 120619, "pn": 19}}', 1400938990000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1424742-math333', 'stk-user8219', 'MATH 333', 'info', '{"desc": "ماتيرال ميجر ون يتكلم عن مسار المنحنيات على الفيكورز (جزء من 201)\nوتكامل منحنيات بإنتيرفال منحنى أو مساحة\n\nسهل بس حلول طويلة\n\nميجر 2\n3/4 عن اللابلاس، سهل بس يحتاج شوية تمرين، وتحتاج كم مهارة من كورسات سابقة (البارشال فراكشن من 102)\n\nالفاينل\nكونسبت، يعني تجيك مسألة حقت فهم نفسها تجيك بالاختبار… مافيه أفكار\nممكن تحفظ، بس إذا دكتورك كويس بسهولة حتفهمها وتحل ببساطة\nوالكتاب شرحه لمتيرايال الفاينال سيء\n(ماتيريال ميجر 1 و2 الكتاب مرة ممتاز)\n\nالكورس بالنسبالي أمتع كورس ماث ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-333-methods-of-applied-mathematics/120619/21", "user": "user8219", "ts": 1440077320000, "tid": 120619, "pn": 21}}', 1440077320000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1456343-math333', 'stk-d111', 'MATH 333', 'info', '{"desc": "-\n\nالكورس ممتع و مو صعب\nبس اللي يتابع من اول و يشد حيله بميجر ١ و ٢\nلكن اذا خبصت في ميجر ١ و ٢ ،، لا تحاول تعوض بالفاينل لأنه ماتريال الفاينل بيكون مستحيل عليك لأنك من اول مضيع 😆", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-333-methods-of-applied-mathematics/120619/23", "user": "D111", "ts": 1472718287000, "tid": 120619, "pn": 23}}', 1472718287000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466102-math333', 'stk-user9202', 'MATH 333', 'info', '{"desc": "ميجر 1 و ميجر 2 في الجيب المفروض\n\nالفاينل عليك بمتابعة الدكتور واحفظ البروسيجر حق الاولد اقزام\n\n( اذا دكتورك محمد يوسف اكتب معااااااااااااااااااااااااه او صور السبورة نصيحة لوجه الله , لان الاسئلة تجي بنفس الفكرة مع تغيير الارقام )\n\nعموما كورس غثيث لكن مو صعب تجيب فيه قريد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-333-methods-of-applied-mathematics/120619/24", "user": "user9202", "ts": 1484146984000, "tid": 120619, "pn": 24}}', 1484146984000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522456-math333', 'stk-trazjaxor', 'MATH 333', 'info', '{"desc": "انا افكر اخذ ماث 333 مع ee 306 في الصيف هذا والدراسة زي منت عارف بتكون عن بعد فياليت اذا اخذتها في الصيف تعطيني رايك وهل كان في ضغط عليك ، محتاج نصيحتك الله يعافيك!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-333-methods-of-applied-mathematics/120619/28", "user": "Trazjaxor", "ts": 1590742800000, "tid": 120619, "pn": 28}}', 1590742800000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533241-math333', 'stk-kjl90', 'MATH 333', 'info', '{"desc": "T211\n\nالكورس متوسط الى صعب\nطريقة المذاكرة واضمن لك قريد عالي:\nاول شي مقاطع الدكتور وليد الخليفي تحصلها في مايكروسوفت ستريم هنا مفييدة جدا\nبعدها خش على أسئلة الكتاب المقترحة تحصلها في السيلابس\nاخر شي اولد اقزام سكشن باي سكشن هنا\nطريقة المذاكرة للفاينل تشابتر 13,14 ,15\nتشوف مقاطع الدكتور وليد وبعدها اولد اقزام على طول بدون ما تحل أسئلة الكتاب; لأن الافكار ما تخرج من الاولداقزام ابدا مذاكرتي للفاينل كانت كذا وجبت 94%.\n\nاتبعت هالطريقة والحمدلله جبت قريد عالي.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-333-methods-of-applied-mathematics/120619/32", "user": "kjl90", "ts": 1641087958000, "tid": 120619, "pn": 32}}', 1641087958000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-as2012sem-math333', 'stk-as2012sem', 'MATH 333', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH333 -191\n\nالتحضير : بشكل يومي ومن اول الكلاس وغير متعاون\nطريقة الشرح : سيئة جدا, الدكتور ارتجالي يجي اوقات يسولف ويضيع وقت الكلاس واوقات يقرا من الكتاب حرفيا ماث ويقرا من الكتاب الدكتور ما يعرف يشرح وما يحل اسئلة عالسبورة ومرة من المرات بدأ الشرح عن درس الfourier series و وقعد اكثر من نص الكلاس يشرح للطلاب ليش الR ما تنطق في fourier\nالكويزات : ارتجالي يجي وقت الكويز ويفتح الكتاب ويختار سؤال ويقول لك حله على ورقة وتصحيحه حسب المزاج اوقات يخسفك اوقات يزبطك لدرجة اشك انه يقرا الحل كامل احيانا\nالمياجر: تصحيح سيئ جدا جدا, الميجر الاول خصم علي 12 بوينت بدون اي داعي وغلط في الجمع كمان في 3 درجات ورحت له الاوفيس ومعاي السلوشن وزادني ال 15 كاملة\nوفي الميجر الثاني غلط في الجمع كمان 🙂\nالدكتور يخسف فيك في المياجر ويقول يلا تعالوا الاوفيس راجعوا الاوراق وتشوف يومها الاوفيس زحمة ويعطيك الورقة يقول اكتب اعتراضك عالكفر بيج واستهبال على كيف كيفك\nالفاينلات : كومن وتصحيحه الصراحة يعطيك حقك\nالقريد النهائي: F\nالصوت: واضح ومسموع\nإضافات : الدكتور لا شرح وولا اخلاق ولا تحضير والدكتور احس لازم يتقاعد ويفكنا خلاص احسه والله ما صار يجمع ويفهم عالطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518554-math333", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/40", "user": "as2012sem", "ts": 1577870367000, "tid": 68413, "pn": 40}}]}', 1577870367000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-trad-math333', 'stk-trad', 'MATH 333', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "203\n\nMATH333 (Online)\n\nالتحضير :\n\nيحضر من التيمز ويحسب كل دقيقة تتاخرها ويجمعها اخر الترم وبعدين يشوف كم متاخر انت وعليها يعتمد هل يزودك ولا لا\n\nطريقة الشرح :\n\nيشرح اول خمس دقايق والباقي كلها يسال الطلاب ويستقعد لهم لين نهاية الكلاس واذا ماجاوبت يحطك في القائمة السودا حقته ويصير يسالك كل كلاس\n\nالكويزات :\n\nالكويزات كان يجيب الاسالة من الكتاب ولكن تصحيحة زفت لابعد درجة تتخيلها\n\nالمياجر: ميدتيرم وهو اللي سواه وكان متوسط الى صعب\n\nالفاينلات : الفاينل سواه هو وكان شق بمعنا الكلمة الافرج تقريبا 39 الى42 بالمية\nالقريد النهائي: D وكثير عليه\n\nالصوت:واضح\nإضافات : بكل شفافية ووضوح الدكتور سيء من جميع النواحي تحاول تدور شي يشفع له ماتحصل. للاسف ماكان فيه الا هو بالصيف وهو كان الكوردنيتر وهو اللي يسوي كل شي من توزيع درجات الى اختبارات…الخ. الدكتور تصحيحة زفت بمعنى الكلمة يحاسبك على كل كبيرة وصغيره وبيجلطك وطبعا اذا ناقشته اسلوبه مش ذاك الزود بيجلس يمصخرك وغصب يطلعك غلطان. اسالته عبارة عن اسالة الكتاب الاخيرة اللي ماحد يحلها ولا حد يجيها واذا ماحليت زين يتعذر ويقولك انا جبت لك اسالة من الكتاب. للاسف اني كنت منحد انزل المادة ولا والله كان حذفت بدون تردد. نصيحتي لك لاتفكر تنزل عنده اذا تبي تحافظ على معدلك وشكرا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531235-math333", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/44", "user": "Trad", "ts": 1628948981000, "tid": 68413, "pn": 44}}]}', 1628948981000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-xz2z-math333', 'stk-xz2z', 'MATH 333', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 213 math333\n١-الدكتور من النوع اللي لا يحطك في راسه لا تمسك جوالك كثير\n٢-عليه حركات مالها داعي مثلا يجيبك فالليل بحجة انكم متأخرين في المنهج لأنه صارله ظرف وغاب وانتم مالكم ذنب\n٣-الدكتور من ناحية الشرح اعطيه ٠٪\n٤-تقييمي لتصحيح الدكتور اذا ما بتراجع معاه ورقتك ٦/١٠\nاذا بتراجع تصحيحه وتعدل غلطاته فالتصحيح ٨.٥/١٠\n٥-قالنا لحد يغيب عشان ازيدكم فالكلاسوورك فالاخير طلع افرجنا مرتفع ونقص ٠.٠٠٧ على اللي غاببوا فوق ٥ غيابات يعني لو دريت كان استعملت كل غياباتي\n٦- كويزاته من الكتاب\nموفقين(:\n\n!لقطة الشاشة 2022-08-16 في 3.31.48 م.png|1128x174](upload://tlg8yFEljmeBbgmauVxItwTbUSC.png)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535041-math333", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/49", "user": "XZ2Z", "ts": 1660653155000, "tid": 68413, "pn": 49}}]}', 1660653155000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-math333', 'stk-guest', 'MATH 333', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math333 | 213\n\nكلام الشخص الي فوقي كافي\nنقطة 1 و 2 اتفق معه\n\nبخصوص شرحه ، فعلا شرحه سيء ولا تتوقع انه بيفيدك بالمياجر من ناحية حل ، لكن بحكم اني كنت فاضي وما ودي اقعد عالجوال ويحطني براسه فكنت اركز بشرحه ، لقيت نفسي استفدت من ناحية كونسبت مما سهل علي المذاكرة ولو بشكل بسيط\nيعني انت كذا ولا كذا بتقعد بالكلاس ، ركز معه ولو بتستفيد 1% افضل من 0%\n\nكويزاته تقهر ، يعني يجيب لك سؤال من الاكسرسايزز الي اخر الدرس ، سؤال واحد وانت وحظك احيان احس انه جايب السؤال ومايعرف اصلا هو السؤال ينحل بدقيقة ولا بساعة\n\nبالنسبة لتصحيحه لازم ، لاااازم تراجع ورقتك مهما كنت مشغول\nالدكتور احيان يلخبط في عد درجات الاسئلة ولا ينقصك ع اشياء مفروض ماينقصك ، صارتلي وبمجرد ماطلبت تعديل ورقتي عدلها ، ماراح يدقق معك اذا معك حق بالزيادة\n\nفيه شي مهم لازم اذكره\nذا الدكتور من النوعية الي اذا كنت معه كويس ولمس منك انك مهتم راح يتساعد معك بشكل كبير\nنصيحتي حاول لاتغيب وركز معه وحاول تبين له انك مهتم قدر الامكان وراح يساعدك\n\nشي ثاني ، قبل لا انزل عند الدكتور قالولي تاخر سنة ولا تنزل عنده ، لكن يوم درست عنده ماكان بهذا السوء\nخصوصا انه فيه مقاطع الخليفي ممتازة وما عانيت من ناحية الشرح\n\nلكن اذا الدكتور كان ماسك المادة لحاله وهو الكوردنيتر ف الله يعينك ولا تنزل عنده ، كلامي بناء على الاولد حقت ترم 203 يوم كان ماسك المادة لحاله جاب اسئلة تعجيزية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535097-math333", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/50", "user": "Guest", "ts": 1661042815000, "tid": 68413, "pn": 50}}]}', 1661042815000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahm2d1-math333', 'stk-ahm2d1', 'MATH 333', 'doc', '{"docs": [{"id": "stk-dr-m68581", "n": "Dr. M Yousuf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 333 - TERM 211 - حضوري\n\nالتحضير : يوزع ورقة ومايدقق وما يخصم على الغياب.\n\nطريقة الشرح : يشرح من النوتات حقته والصراحه النوتات حقته ممتازه اغلب اللي منزلين الكورس يذاكرون منها وتكفي ، بالنسبه لشرحه جيد.\n\nالكويزات : اختبرنا ٥ كويزات وخذا افضل ٤ وكويزاته متوسطه.\n\nالمياجر: المياجر في هذا الترم ما كانت صعبه اغلبها نفس افكار النوتات واسئلة الكتاب.\nافرج الميجر الاول: ٦٣٪؜\nوالثاني: ٦٨٪؜\nوالفاينل: ٧٥٪؜\n\nالصوت: صوته واضح والكل يسمعه.\n\nإضافات : الدكتور اسلوبه سيء و دايم ضد الطالب.\nنظامه في التصحيح اذا كان السوال عليه ١٥ بوينت يا تحل صح وتاخذ ١٥ يا بيعطيك ١ او ٢ من ١٥ حتى لو كان نص حلك صحيح عشان كذا اشوف تصحيح الدكتور سيء.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533214-math333", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-yousuf/68581/44", "user": "Ahm2d1", "ts": 1640925385000, "tid": 68581, "pn": 44}}]}', 1640925385000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-math333', 'stk-user11372', 'MATH 333', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH333 - Term221\n\nالتحضير : الدكتور متساهل شوي بالتحضير للامانه يعني لو جيت بعد 15 دقيقة او نص ساعة بيعطيك حضور\n\nطريقة الشرح : صراحة بداية الكورس شرحه كان جيد بس نهاية الكورس ماعرف وش المشكلة صارت لدرجة محد صار يفهم شي وعبارة عن تسليك الكلاس\nفا نقول عموما شرحه جيد\n\nالكويزات : اختبرنا تقريبا 4 كويزات مستواها كان جيد كلها من الاولد اقزام تجي نفس الافكار نسخ لصق بس هو يقول ياخذها من الكتاب\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي للدكتور : C (وبقول ليش تحت)\n\nالصوت: واضح\n\nإضافات : الدكتور صراحة تعامله بالتصحيح جدا جدا سيئ ويعطيك اقل مايمكن + الاوفيس اذا رحت تسأله غير متجاوب ابدا ابدا\nاذا بتسأله سؤال بالكلاس مابتحصل جواب بيقول مفروض عارفه ومدري وش\nواضافة لكذا نهاية كل كلاس حول 20 دقيقة يقعد يسولف وخلص الشرح بس يقعد يسولف يسولف على الفاضي ولا حنا استفدنا من الوقت ولا شي\nوزيد على هذا كله الافرج للسكشن حقه دايم بالارض والطلاب مو فاهمين وضايعين اغلب الوقت\n+\nلازم تتغير الفكرة اللي فوق بالموقع انه يدف بالتصحيح وكذا صار حقاني الدكتور مره ويعطيك اقل بعد من حقك يمكن للامانه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536131-math333", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/79", "user": "user11372", "ts": 1673082368000, "tid": 68928, "pn": 79}}]}', 1673082368000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wil.e-math333', 'stk-wil.e', 'MATH 333', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math333 - Term 202\nبنود التقييم :\n\nأول شي صلّ على النبي،\n\nالتحضير : كان يفتح رابط نهاية الكلاس والعيال يحضرون انفسهم\n\nطريقة الشرح : سلايداته ويكتب عليهم الخطوات وكل شي، وللامانة سلايداته وسط ما يعتمد عليها ولكنها كشرح تشرح الأفكار المختلفة\n\nالكويزات : لا تضيعها ابدا ابدا سهالات باذن الله بس محتاج شوية براكتس على الهوموورك وامورك طيبة ان شاء الله\n\nالمياجر: كان ميد وصراحة وسط بس الاختياري كان مخرب كل شي، ولكن تصحيح الدكتور بطل وانا متاكد عطاني حقي وزيادة ما قصر\n\nالفاينلات : الفاينل والماتيريال حقه حفظxحفظ حرفيا عبارة عن شي تكتبه كم مرة قبل الاختبار وتجي تكتبه مرة ثانية، الماتيريال صعب شوي بس الدكتور بيحاول يوضح لك الفكرة\n\nالقريد النهائي: A\n\nالصوت: واضح\n\nإضافات : تصحيحه حلو ويحب مشاركة الطلاب معه لذلك يعتبر خيار حلو للي وده يدرس مادته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529932-math333", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/28", "user": "wil.e", "ts": 1620554835000, "tid": 92906, "pn": 28}}]}', 1620554835000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abofordan2004-math333', 'stk-abofordan2004', 'MATH 333', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 333 - TERM 212\nالدكتور: محمد كفيني\nالتحضير: مايكروسوفت فورم يفتحه نهاية كل حصة, واخر الترم صار يحضر بالسيريال نمبر لان العيال مصخوها بالغيابات وكل واحد يحضر من البيت.\nالتعامل: ممتاز وطيب لكن نصيحة اخ لا تجلس قدامه لانه بيطقطق عليك في كل حصة طول الترم.\nالشرح: جيد ولكن محد مننا كان حوله لأن اغلبنا كان معتمد على تسجيل شرح الخليفي.\nالصوت: واضح.\nالكويزات: متوسطة بس قبل ما تاخذ الكويز تاكد انك تحل من Old Exams Section By section على الدرس اللي بتختبر فيه, وانتبه تستهون في واحد منها او تسحب عليه لان في نهاية الترم ياخذ ثلاث كويزات فقط والواحد علية 5%.\nالتصحيح: اشوفه جيد ويدف شوي.\nالمياجر: كومن.\nالفاينل: كومن.\nالقريد B.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534474-math333", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/30", "user": "AboFordan2004", "ts": 1653652434000, "tid": 92906, "pn": 30}}]}', 1653652434000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nasalmz-math333', 'stk-nasalmz', 'MATH 333', 'doc', '{"docs": [{"id": "stk-dr-m118579", "n": "Dr. W Al-Khulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM-193 (online) MATH-333\n\nطبعا بعد 192 اغلب الدكاترة اخذوا فكرة كيف يتعاملون مع الدراسة عن بعد و دكتور وليد صراحة ماقصر يشرح ويكتب ويفتح مجال للأسئلة.\nوكنا نستخدم مايكروسوفت تيمز.\n\nالتحضير: طول الترم حضر عن طريق التيمز ينبهنا ويوقف اللكتشر ويقول روحو حلو الاتندانس كويز طبعا الكويز خيار واحد يعني تحط وتمشي.\nالشرح: من اول محاضرة كان يسوي “share screen” للسلايدات اللي هو مسويها ويشرح شفويا القواعد ويبين الامثلة اللي بنحلها ويتنقل بين السلايدات وبعدين يسوي “share” لكاميرا حقت جوالة وهو مثبت جوالة ع ترايبود ويشرح ويحل ع اوراق A3 طبعا الشرح واضح ومو موشوش ويوضح الخطوات بالملي.\nالصوت: الصوت واضح جدا.\n“الكورس من 300 point”\nاضافات: نجي الحين لجزئية الترم الصيفي واختباراته والاوفس اورز وكل هالكلام.\nالاختبارات:“كلها رتن” ماتيرال المادة موزع على 8 اسابيع ومن بداية الترم كنا عارفين سياسة الاختبارات بالنسبة لهذا الكورس لأن دكتور وليد كان هو الكوردنيتر حق المادة. كانت 6 اختبارات اسبوعية وبدينا اختبارات من الاسبوع الثاني وكان ماتيريال اول اختبار كان على الدروس في الاسبوع الاول و الاختبار الثاني كان في الاسبوع الثالث وماتيريال الاختبار هي الدروس في االاسبوع الثاني و… لين ما خلصنا ال 6 اختبارات وكان عليهن 230 point واسوأ اختبار كان محذوف.\nالفاينل: الله يجزاه خير اول واخر كورس ماث في الجامعة اخذته الفاينل مو comprehensive وكانت الدروس محددة لأن لو تشوف الشرح للأختبارات اللي ذكرتها، الاسبوع الاخير ماراح نختبر عليه لان مافيه اسبوع بعده. لكن ماتيريال الفاينل كان على ال 4 دروس الاخيرة في الاسبوع الأخير مع 3 دروس من اول إختبار اختبرناه. وكان عليه 60 point.\nالكلاسوورك: 10 point وكان بس على حضورك في الكلاسات وكان كل غياب عليه خصم 0.5 point.\nالأوفس اورز: بعد كل كلاس الدكتور يسأل احد عنده سؤال استفسار واللي يبي يسأله يقول انتظر شوي واستمرينا على هذا الموال لين نهاية الترم.\n\nكيف اختبرنا الاختبرات: من قبل لا ناخذ اول محاضرة وحنا عارفين كيف سياسة الاختبار واللي هي في مرحلة ال checking in بعدين نختبر بعدين checking out في اول اختبار حصل تأخيركثير من جهه الدكتور لأنها اول مره بس الاختبارات الباقية والفاينل كلها سوينا العملية بسرعه. كنا نفتح الكاميرا الزوم والاسئلة ع البلاكبورد نحل ونصور pdf ونسلم ووقت التسليم من الاختبار يعني خلص الوقت عليك مشكلتك حبيبي مو مشكلة الدكتور في ناس لقموا السالفة هذه ف الاختبار الاول وهجت معهم لكن بعد الاختبار الاول ما اتوقع المشكلة صارت ثاني مره.\n\nصراحة التجربة كانت حلوة وضغط والمادة كريهه شوي بس خلاص من حبكم يازين عزلنا مع السلامة يا قسم الماث وختامها مسك مع الدكتور وليد.\n\nيارب 201 حضور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524325-math333", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-al-khulaifi/118579/22", "user": "Nasalmz", "ts": 1595943131000, "tid": 118579, "pn": 22}}]}', 1595943131000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
